package com.lhbaptist.kjvapp;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Typeface;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;

public class MainActivity extends Activity {
 JSONArray bible; int bi=42, ci=2; LinearLayout root, verses; TextView title; ScrollView scroll; SharedPreferences prefs; float font=25f;
 int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);} TextView tv(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(0xff000000);v.setPadding(dp(12),dp(10),dp(12),dp(10));return v;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(18);b.setMinHeight(dp(56));b.setAllCaps(false);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("kjv",0);bi=prefs.getInt("book",42);ci=prefs.getInt("chapter",2);font=prefs.getFloat("font",25f);try{InputStream in=getAssets().open("kjv.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);in.close();bible=new JSONArray(new String(out.toByteArray(),StandardCharsets.UTF_8));}catch(Exception e){fatal(e.toString());return;}showReader(-1);}
 void fatal(String s){TextView v=tv(s,20);setContentView(v);} void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xffffffff);setContentView(root);}
 void showReader(int verse){try{base();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);Button books=btn("☰ Books");title=tv("",22);title.setTypeface(null,Typeface.BOLD);title.setGravity(Gravity.CENTER);Button search=btn("Search");top.addView(books,new LinearLayout.LayoutParams(0,dp(62),1));top.addView(title,new LinearLayout.LayoutParams(0,dp(62),2));top.addView(search,new LinearLayout.LayoutParams(0,dp(62),1));root.addView(top);books.setOnClickListener(v->showBooks());search.setOnClickListener(v->showSearch());title.setOnClickListener(v->showChapters());scroll=new ScrollView(this);verses=new LinearLayout(this);verses.setOrientation(LinearLayout.VERTICAL);scroll.addView(verses);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bottom=new LinearLayout(this);Button prev=btn("‹ Previous"),chap=btn("Chapters"),next=btn("Next ›");bottom.addView(prev,new LinearLayout.LayoutParams(0,dp(66),1));bottom.addView(chap,new LinearLayout.LayoutParams(0,dp(66),1));bottom.addView(next,new LinearLayout.LayoutParams(0,dp(66),1));root.addView(bottom);prev.setOnClickListener(v->move(-1));next.setOnClickListener(v->move(1));chap.setOnClickListener(v->showChapters());render(verse);}catch(Exception e){fatal(e.toString());}}
 void render(int target)throws Exception{JSONObject book=bible.getJSONObject(bi),ch=book.getJSONArray("chapters").getJSONObject(ci);title.setText(book.getString("book")+" "+ch.getString("chapter"));JSONArray vv=ch.getJSONArray("verses");TextView targetView=null;for(int i=0;i<vv.length();i++){JSONObject q=vv.getJSONObject(i);TextView v=tv(q.getString("verse")+"  "+q.getString("text"),(int)font);v.setLineSpacing(0,1.22f);verses.addView(v);if(i+1==target)targetView=v;}prefs.edit().putInt("book",bi).putInt("chapter",ci).apply();if(targetView!=null){TextView f=targetView;scroll.post(()->scroll.scrollTo(0,f.getTop()));}}
 void move(int d){try{ci+=d;if(ci<0){if(bi>0){bi--;ci=bible.getJSONObject(bi).getJSONArray("chapters").length()-1;}else ci=0;}int n=bible.getJSONObject(bi).getJSONArray("chapters").length();if(ci>=n){if(bi<bible.length()-1){bi++;ci=0;}else ci=n-1;}showReader(-1);}catch(Exception e){}}
 void showBooks(){try{base();root.addView(tv("Choose a Book",28));ScrollView s=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);s.addView(list);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));for(int i=0;i<bible.length();i++){final int x=i;Button b=btn(bible.getJSONObject(i).getString("book"));list.addView(b);b.setOnClickListener(v->{bi=x;ci=0;showChapters();});}}catch(Exception e){}}
 void showChapters(){try{base();JSONObject book=bible.getJSONObject(bi);LinearLayout h=new LinearLayout(this);Button back=btn("‹ Bible");TextView t=tv(book.getString("book"),28);t.setGravity(Gravity.CENTER);h.addView(back,new LinearLayout.LayoutParams(0,dp(64),1));h.addView(t,new LinearLayout.LayoutParams(0,dp(64),3));root.addView(h);back.setOnClickListener(v->showBooks());ScrollView s=new ScrollView(this);GridLayout g=new GridLayout(this);g.setColumnCount(5);s.addView(g);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));int n=book.getJSONArray("chapters").length();for(int i=0;i<n;i++){final int x=i;Button b=btn(String.valueOf(i+1));GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=dp(70);p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1,1f);g.addView(b,p);b.setOnClickListener(v->{ci=x;showReader(-1);});}}catch(Exception e){}}
 void showSearch(){base();root.addView(tv("Search the KJV",28));EditText q=new EditText(this);q.setTextSize(22);q.setHint("Word, phrase, or reference (John 3:16)");q.setSingleLine(true);q.setMinHeight(dp(62));root.addView(q);LinearLayout bar=new LinearLayout(this);Button go=btn("Search"),close=btn("Back to Bible");bar.addView(go,new LinearLayout.LayoutParams(0,dp(64),1));bar.addView(close,new LinearLayout.LayoutParams(0,dp(64),1));root.addView(bar);ScrollView s=new ScrollView(this);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);s.addView(results);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));close.setOnClickListener(v->showReader(-1));go.setOnClickListener(v->{String z=q.getText().toString().trim();if(goReference(z))return;results.removeAllViews();search(z,results);((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(q.getWindowToken(),0);});q.requestFocus();}
 boolean goReference(String z){Matcher m=Pattern.compile("(?i)^(.+?)\\s+(\\d+)(?::(\\d+))?$").matcher(z);if(!m.matches())return false;String name=m.group(1).replaceAll("[.]","").trim();try{for(int i=0;i<bible.length();i++){String b=bible.getJSONObject(i).getString("book");if(b.equalsIgnoreCase(name)||abbr(b).equalsIgnoreCase(name)){int c=Integer.parseInt(m.group(2))-1;if(c>=0&&c<bible.getJSONObject(i).getJSONArray("chapters").length()){bi=i;ci=c;showReader(m.group(3)==null?-1:Integer.parseInt(m.group(3)));return true;}}}}catch(Exception e){}return false;}
 String abbr(String b){return b.replace("Genesis","Gen").replace("Exodus","Ex").replace("Psalms","Ps").replace("Proverbs","Prov").replace("Matthew","Matt").replace("Mark","Mk").replace("Luke","Lk").replace("John","Jn").replace("Corinthians","Cor").replace("Thessalonians","Thes").replace("Timothy","Tim").replace("Peter","Pe").replace("Revelation","Rev");}
 void search(String z,LinearLayout out){if(z.length()==0)return;String needle=z.toLowerCase(Locale.US);int count=0;try{outer:for(int b=0;b<bible.length();b++){JSONObject bo=bible.getJSONObject(b);JSONArray cc=bo.getJSONArray("chapters");for(int c=0;c<cc.length();c++){JSONObject ch=cc.getJSONObject(c);JSONArray vv=ch.getJSONArray("verses");for(int v=0;v<vv.length();v++){JSONObject x=vv.getJSONObject(v);String text=x.getString("text");boolean hit=needle.contains(" ")?text.toLowerCase(Locale.US).contains(needle):Pattern.compile("(?i)(?<![A-Za-z])"+Pattern.quote(needle)+"(?![A-Za-z])").matcher(text).find();if(hit){final int fb=b,fc=c,fv=v+1;TextView r=tv(bo.getString("book")+" "+ch.getString("chapter")+":"+x.getString("verse")+"\n"+text,20);r.setPadding(dp(14),dp(14),dp(14),dp(14));out.addView(r);r.setOnClickListener(w->{bi=fb;ci=fc;showReader(fv);});if(++count>=50)break outer;}}}}if(count==0)out.addView(tv("No matches found.",20));else if(count==50)out.addView(tv("Showing first 50 matches. Refine the search to narrow the results.",18));}catch(Exception e){out.addView(tv(e.toString(),18));}}
}
